function validatePayload(data) {
  const errors = [];
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return { isValid: false, errors: ['Payload must be a valid object.'] };
  }
  const validCategories = ['billing', 'technical', 'account', 'sales', 'other'];
  if (!('category' in data)) {
    errors.push('category is required.');
  } else if (typeof data.category !== 'string') {
    errors.push('category must be a string.');
  } else if (!validCategories.includes(data.category)) {
    errors.push(`category must be one of: ${validCategories.join(', ')}.`);
  }
  if (!('summary' in data)) {
    errors.push('summary is required.');
  } else if (typeof data.summary !== 'string') {
    errors.push('summary must be a string.');
  } else if (data.summary.trim() === '') {
    errors.push('summary must not be empty.');
  }
  if (!('requested_action' in data)) {
  errors.push('requested_action is required.');
} else {
  const action = data.requested_action;

  if (action !== null) {
    if (typeof action !== 'string') {
      errors.push('requested_action must be a string or null.');
    } else if (action.trim() === '') {
      errors.push('requested_action, if provided as a string, must not be empty.');
    }
  }
}
  const validUrgencies = ['low', 'medium', 'high'];
  if (!('urgency' in data)) {
    errors.push('urgency is required.');
  } else if (typeof data.urgency !== 'string') {
    errors.push('urgency must be a string.');
  } else if (!validUrgencies.includes(data.urgency)) {
    errors.push(`urgency must be one of: ${validUrgencies.join(', ')}.`);
  }
  if (!('needs_review' in data)) {
    errors.push('needs_review is required.');
  } else if (typeof data.needs_review !== 'boolean') {
errors.push('needs_review must be a strict boolean (true or false).');
  }
  return {
    isValid: errors.length === 0,
    errors,
  };
}
