/**
 * Routes an extracted ticket object to automatic processing or human review
 * based on deterministic business rules.
 * 
 * @param {Object} ticket - The validated AI output.
 * @returns {Object} - Result containing decision boolean and array of reasons.
 */
function routeForReview(ticket) {
  const reasons = [];


  if (ticket.needs_review === true) {
    reasons.push("AI flagged ticket as ambiguous or uncertain (needs_review: true).");
  }


  const action = (ticket.requested_action || "").toLowerCase();
  if (action.includes("refund")) {
    reasons.push("Refund request requires human approval");
  }

  if (ticket.category === "account") {
    const textToScan = `${ticket.summary || ""} ${ticket.requested_action || ""}`.toLowerCase();

    const securityKeywords = [
      "ownership", 
      "compromise", 
      "compromised", 
      "unauthorized", 
      "hacked", 
      "takeover", 
      "access issue",
      "security"
    ];

    const hasSecurityIssue = securityKeywords.some(keyword => textToScan.includes(keyword));

    if (hasSecurityIssue) {
      reasons.push("Account ticket involves security, access compromise, or ownership issue.");
    }
  }


  if (ticket.urgency === "high") {
    reasons.push("Ticket marked with high urgency.");
  }

  if (ticket.category === "other") {
    reasons.push("Ticket categorized under unclassified 'other' category.");
  }

  return {
    needsHumanReview: reasons.length > 0,
    reasons: reasons
  };
}

const items = $input.all();
const ticket = items[0].json;

const reviewResult = routeForReview(ticket);

return [
  {
    json: {
      ...ticket,
      needs_human_review: reviewResult.needsHumanReview,
      review_reasons: reviewResult.reasons
    }
  }
];
